-- d1PreparationStepsSchema
CREATE TABLE IF NOT EXISTS ik_d1_preparation_steps (id TEXT PRIMARY KEY, destination TEXT NOT NULL, namespace TEXT NOT NULL, mapping_version TEXT NOT NULL, principal_id TEXT NOT NULL, operation_key TEXT NOT NULL, reversal_policy TEXT NOT NULL, codec_id TEXT, source_digest TEXT NOT NULL, total INTEGER NOT NULL, records INTEGER NOT NULL DEFAULT 0, stages TEXT NOT NULL DEFAULT '[]', phase TEXT NOT NULL CHECK(phase IN ('collecting','hashing','combining','prepared')), hash_json TEXT, fingerprint TEXT, verified_revision INTEGER, revision INTEGER NOT NULL DEFAULT 0, UNIQUE(destination,principal_id,operation_key));
CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_binding BEFORE UPDATE OF id,destination,namespace,mapping_version,principal_id,operation_key,reversal_policy,codec_id,source_digest,total ON ik_d1_preparation_steps BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_BINDING_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_preparation_steps_revision BEFORE UPDATE ON ik_d1_preparation_steps WHEN NEW.revision<>OLD.revision+1 BEGIN SELECT RAISE(ABORT,'IMPORT_PREPARATION_CHANGED'); END;
CREATE TABLE IF NOT EXISTS ik_d1_stream_sources (stream_id TEXT PRIMARY KEY REFERENCES ik_d1_streams(id) ON DELETE CASCADE, destination TEXT NOT NULL, source_digest TEXT NOT NULL);

-- d1RetirementSchema
CREATE TABLE IF NOT EXISTS ik_d1_retirements (id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('job','stream')), destination TEXT NOT NULL, receipt_id TEXT NOT NULL, retired_at TEXT NOT NULL, PRIMARY KEY(id, kind));
CREATE TABLE IF NOT EXISTS ik_d1_erasure_journal (id TEXT PRIMARY KEY, destination TEXT NOT NULL, recorded_at TEXT NOT NULL, records_erased INTEGER NOT NULL CHECK(records_erased>=0), jobs_retired INTEGER NOT NULL CHECK(jobs_retired>=0), streams_retired INTEGER NOT NULL CHECK(streams_retired>=0), stores_json TEXT NOT NULL CHECK(json_valid(stores_json)));
CREATE INDEX IF NOT EXISTS ik_d1_erasure_journal_time ON ik_d1_erasure_journal(destination, recorded_at);
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_insert BEFORE INSERT ON ik_d1_erasure_journal WHEN EXISTS(SELECT 1 FROM ik_d1_erasure_journal WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_insert BEFORE INSERT ON ik_d1_retirements WHEN EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=NEW.id AND kind=NEW.kind) BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_update BEFORE UPDATE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_journal_delete BEFORE DELETE ON ik_d1_erasure_journal BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_JOURNAL_APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_update BEFORE UPDATE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_retirement_delete BEFORE DELETE ON ik_d1_retirements BEGIN SELECT RAISE(ABORT,'IMPORT_RETIREMENT_CHANGED'); END;
CREATE TABLE IF NOT EXISTS ik_d1_erasure_tally (receipt_id TEXT NOT NULL, store TEXT NOT NULL, image TEXT NOT NULL);
DROP TRIGGER IF EXISTS ik_d1_stream_revision_update;
CREATE TRIGGER ik_d1_stream_revision_update BEFORE UPDATE ON ik_d1_stream_revisions WHEN NEW.stream_id IS NOT OLD.stream_id OR NEW.destination IS NOT OLD.destination OR NEW.mapping_version IS NOT OLD.mapping_version OR NEW.principal_id IS NOT OLD.principal_id OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.total IS NOT OLD.total OR NEW.layout_hash IS NOT OLD.layout_hash OR NEW.layout_revision<OLD.layout_revision OR NEW.progress_revision<=OLD.progress_revision OR ((NEW.namespace IS NOT OLD.namespace OR NEW.operation_key IS NOT OLD.operation_key) AND NOT (NEW.namespace='' AND NEW.operation_key='' AND NOT EXISTS(SELECT 1 FROM ik_d1_streams WHERE id=OLD.stream_id) AND EXISTS(SELECT 1 FROM ik_d1_retirements WHERE id=OLD.stream_id AND kind='stream'))) BEGIN SELECT RAISE(ABORT,'IMPORT_STREAM_REVISION_CHANGED'); END;
-- Native revision token belongs to the same atomic commit as the import journal.
ALTER TABLE pl_jobs ADD COLUMN import_revision TEXT;

-- Subscription secrets are returned once; only their SHA-256 digests persist.
CREATE TABLE pl_calendar_tokens (
 token_hash TEXT PRIMARY KEY NOT NULL CHECK(length(token_hash)=64),
 person_id TEXT NOT NULL REFERENCES oa_operators(id) ON DELETE CASCADE,
 job_id TEXT NOT NULL REFERENCES pl_jobs(id) ON DELETE CASCADE,
 UNIQUE(person_id,job_id)
);
CREATE INDEX pl_calendar_token_job ON pl_calendar_tokens(job_id);

CREATE TABLE pl_schedule_constraint_files (
 id TEXT PRIMARY KEY,
 job_id TEXT NOT NULL REFERENCES pl_jobs(id) ON DELETE CASCADE,
 bytes BLOB NOT NULL
);

-- SUB-001 subcontractor and vendor directory; W-9 originals stay private beside it.
CREATE TABLE pl_vendors(id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version > 0), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE pl_vendor_documents(id TEXT PRIMARY KEY NOT NULL, vendor_id TEXT NOT NULL REFERENCES pl_vendors(id) ON DELETE CASCADE, name TEXT NOT NULL, mime TEXT NOT NULL, checksum TEXT NOT NULL, size INTEGER NOT NULL CHECK(size BETWEEN 1 AND 2097152), bytes BLOB NOT NULL CHECK(length(bytes)=size));
CREATE INDEX pl_vendor_document_vendor ON pl_vendor_documents(vendor_id);

-- SUB-004 owner waiver wording per state (optionally per job) and the signed release originals of each job.
CREATE TABLE pl_lien_waiver_templates(id INTEGER PRIMARY KEY CHECK(id = 1), version INTEGER NOT NULL CHECK(version > 0), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE pl_lien_waiver_files (
 id TEXT PRIMARY KEY,
 job_id TEXT NOT NULL REFERENCES pl_jobs(id) ON DELETE CASCADE,
 bytes BLOB NOT NULL
);

CREATE TABLE pl_report_config(id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE pl_report_values(record_scope TEXT NOT NULL, record_id TEXT NOT NULL, job_id TEXT REFERENCES pl_jobs(id) ON DELETE CASCADE, version INTEGER NOT NULL, stage TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(record_scope,record_id));
CREATE TABLE pl_report_views(id TEXT PRIMARY KEY, version INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));

-- Transient cursor only: agreement authority and attempts remain in the job.
CREATE TABLE pl_warranty_scheduler (id INTEGER PRIMARY KEY CHECK(id=1), last_rowid INTEGER NOT NULL);
INSERT INTO pl_warranty_scheduler(id,last_rowid) VALUES(1,0);

CREATE TABLE pl_invoice_sequence (
 id INTEGER PRIMARY KEY CHECK (id = 1),
 next_number INTEGER NOT NULL CHECK (next_number > 0 AND next_number <= 1000000000000)
);
INSERT INTO pl_invoice_sequence(id,next_number) VALUES(1,1);

-- Additive Base rer-v0.2.79 schema adoption; preserve previously applied migrations.

-- Apply as a NEW numbered migration. Authority and audit are durable, not sessions.
CREATE TABLE IF NOT EXISTS oa_policy_approvals (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL, version_hash TEXT NOT NULL,
 definition TEXT NOT NULL, actions TEXT NOT NULL,
 owner_id TEXT NOT NULL REFERENCES oa_operators(id), owner_version INTEGER NOT NULL,
 approved_at INTEGER NOT NULL, revoked_at INTEGER,
 session_kind TEXT NOT NULL, revoke_reason TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS oa_policy_live ON oa_policy_approvals(policy_id) WHERE revoked_at IS NULL;
CREATE TABLE IF NOT EXISTS oa_policy_runs (
 id TEXT PRIMARY KEY, policy_id TEXT NOT NULL, version_hash TEXT,
 approval_id TEXT REFERENCES oa_policy_approvals(id), approved_by TEXT,
 started_at INTEGER NOT NULL, finished_at INTEGER,
 status TEXT NOT NULL CHECK(status IN ('running','completed','refused','failed')), error TEXT,
 admitted INTEGER NOT NULL DEFAULT 0, repeats INTEGER NOT NULL DEFAULT 1, last_seen_at INTEGER
);
CREATE INDEX IF NOT EXISTS oa_policy_runs_time ON oa_policy_runs(started_at DESC);
CREATE INDEX IF NOT EXISTS oa_policy_action_run ON oa_auth_audit(CASE WHEN json_valid(value) THEN json_extract(value,'$.runId') END,action);

-- Apply as a NEW numbered migration after any oa_sessions rebuild.
-- Never infer inactivity from missing credentials: older sessions may have been
-- pruned. Existing operators receive a full inactivity window from this upgrade.
ALTER TABLE oa_operators ADD COLUMN last_signin_at INTEGER;
UPDATE oa_operators SET last_signin_at=MAX(
 created_at, CAST(strftime('%s','now') AS INTEGER)*1000+999,
 COALESCE((SELECT MAX(created_at) FROM oa_sessions WHERE operator_id=oa_operators.id),0)
);
CREATE TRIGGER oa_record_last_signin AFTER INSERT ON oa_sessions
 BEGIN UPDATE oa_operators SET last_signin_at=NEW.created_at
 WHERE id=NEW.operator_id AND (last_signin_at IS NULL OR last_signin_at<NEW.created_at); END;

ALTER TABLE rer_dependency_installation ADD COLUMN keys_sealed INTEGER NOT NULL DEFAULT 0 CHECK(keys_sealed IN (0,1));
-- Nonsecret version history lets restored rows name an unavailable retired key
-- without confusing ciphertext tampering or a wrong current secret with restore.
ALTER TABLE rer_dependency_installation ADD COLUMN key_ids TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(key_ids) AND json_type(key_ids)='array');

-- Standing receiver authority and its retry history remain installation-local.
ALTER TABLE pl_connector_subscriptions ADD COLUMN grant_id TEXT;
ALTER TABLE pl_connector_subscriptions ADD COLUMN grant_origin TEXT;
ALTER TABLE pl_connector_subscriptions ADD COLUMN grant_event_types TEXT;
ALTER TABLE pl_connector_subscriptions ADD COLUMN grant_payload_class TEXT;
ALTER TABLE pl_connector_subscriptions ADD COLUMN grant_rate_cap INTEGER;
ALTER TABLE pl_connector_subscriptions ADD COLUMN grant_expires_at TEXT;
ALTER TABLE pl_connector_subscriptions ADD COLUMN grant_revoked_at TEXT;
ALTER TABLE pl_connector_subscriptions ADD COLUMN grant_after INTEGER NOT NULL DEFAULT 0;
ALTER TABLE pl_connector_subscriptions ADD COLUMN paused_at TEXT;
ALTER TABLE pl_connector_subscriptions ADD COLUMN pause_reason TEXT;
ALTER TABLE pl_connector_subscriptions ADD COLUMN failure_count INTEGER NOT NULL DEFAULT 0;
ALTER TABLE pl_connector_deliveries ADD COLUMN consent_grant_id TEXT;
ALTER TABLE pl_connector_deliveries ADD COLUMN mode TEXT NOT NULL DEFAULT 'manual';
ALTER TABLE pl_connector_deliveries ADD COLUMN retry_at TEXT;
CREATE INDEX pl_connector_event_attempts ON pl_connector_deliveries(subscription_id,event_id,started_at);
-- A durable sequence cannot reuse an erased event's position at the grant boundary.
CREATE TABLE pl_connector_event_order (
 sequence INTEGER PRIMARY KEY AUTOINCREMENT,
 event_id TEXT NOT NULL UNIQUE REFERENCES pl_connector_events(id) ON DELETE CASCADE
);
INSERT INTO pl_connector_event_order(event_id) SELECT id FROM pl_connector_events ORDER BY rowid;

-- Settlement facts and a durable, unresolved provider instruction survive delayed events.
ALTER TABLE pl_payment_attempts ADD COLUMN settlement_state TEXT NOT NULL DEFAULT 'initiated';
ALTER TABLE pl_payment_attempts ADD COLUMN request_json TEXT;
ALTER TABLE pl_payment_attempts ADD COLUMN reversed_cents INTEGER NOT NULL DEFAULT 0;
ALTER TABLE pl_payment_attempts ADD COLUMN reconciled_at TEXT;
ALTER TABLE pl_payment_attempts ADD COLUMN revision INTEGER NOT NULL DEFAULT 0;
UPDATE pl_payment_attempts SET settlement_state=CASE status WHEN 'paid' THEN 'settled' WHEN 'review' THEN 'settled' WHEN 'expired' THEN 'canceled' ELSE CASE WHEN status='open' THEN 'initiated' ELSE status END END;
CREATE UNIQUE INDEX pl_payment_intent ON pl_payment_attempts(payment_intent_id) WHERE payment_intent_id IS NOT NULL;
CREATE TABLE pl_payment_refunds (
 id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES pl_payment_attempts(id) ON DELETE CASCADE,
 amount_cents INTEGER NOT NULL CHECK(amount_cents>0), reason TEXT NOT NULL, created_by TEXT NOT NULL,
 status TEXT NOT NULL, provider_id TEXT, created_at TEXT NOT NULL
);
CREATE UNIQUE INDEX pl_payment_refund_pending ON pl_payment_refunds(attempt_id) WHERE status='unresolved';

CREATE TABLE IF NOT EXISTS agent_door_state (
  id INTEGER PRIMARY KEY CHECK(id=1), envelope TEXT, local_document TEXT,
  local_revision INTEGER NOT NULL DEFAULT 0, local_paused INTEGER NOT NULL DEFAULT 0,
