-- An INSERT of NULL fails the transaction if a concurrent write invalidated its fence.
CREATE TABLE bs_assert (value INTEGER NOT NULL);

ALTER TABLE bs_settings ADD COLUMN owner_id TEXT CHECK(owner_id IS NULL OR owner_id <> '');
ALTER TABLE bs_team ADD COLUMN business_id TEXT CHECK(business_id IS NULL OR business_id <> '');
ALTER TABLE bs_team ADD COLUMN business_role TEXT CHECK(business_role IS NULL OR business_role IN('admin','member'));
CREATE UNIQUE INDEX bs_team_business_id ON bs_team(business_id) WHERE business_id IS NOT NULL;

-- A private snapshot and bounded output checkpoints survive a process restart.
CREATE TABLE pl_background_work(
 id TEXT PRIMARY KEY,
 version INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('paused','complete','failed','cancelled')),
 owner_id TEXT NOT NULL,
 format TEXT NOT NULL CHECK(format IN ('csv','xlsx')),
 created_at TEXT NOT NULL,
 data TEXT NOT NULL CHECK(json_valid(data)),
 progress INTEGER NOT NULL DEFAULT 0,
 total INTEGER NOT NULL,
 error TEXT,
 checksum TEXT
);
CREATE TABLE pl_background_sources(
 task_id TEXT NOT NULL REFERENCES pl_background_work(id) ON DELETE CASCADE,
 record_scope TEXT NOT NULL,
 record_id TEXT NOT NULL,
 job_id TEXT,
 PRIMARY KEY(task_id,record_id)
);
CREATE TABLE pl_background_chunks(
 task_id TEXT NOT NULL REFERENCES pl_background_work(id) ON DELETE CASCADE,
 sequence INTEGER NOT NULL,
 source TEXT NOT NULL CHECK(json_valid(source)),
 output TEXT,
 PRIMARY KEY(task_id,sequence)
);
-- Deliberately excluded from archives: restored tasks have no execution authority.
CREATE TABLE pl_background_reviews(task_id TEXT PRIMARY KEY REFERENCES pl_background_work(id) ON DELETE CASCADE, owner_id TEXT NOT NULL, digest TEXT NOT NULL);
CREATE TRIGGER pl_background_job_erasure BEFORE DELETE ON pl_jobs BEGIN
 DELETE FROM pl_background_work WHERE id IN (SELECT task_id FROM pl_background_sources WHERE job_id=OLD.id);
END;
CREATE TRIGGER pl_background_customer_erasure BEFORE DELETE ON pl_customers BEGIN
 DELETE FROM pl_background_work WHERE id IN (SELECT task_id FROM pl_background_sources WHERE record_scope='customer' AND record_id=OLD.id);
END;
CREATE TRIGGER pl_background_vendor_erasure BEFORE DELETE ON pl_vendors BEGIN
 DELETE FROM pl_background_work WHERE id IN (SELECT task_id FROM pl_background_sources WHERE record_scope='vendor' AND record_id=OLD.id);
END;

-- Historical analysis is portable; permission to expose it to an agent is installation-local.
CREATE TABLE pl_learning_packets(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE pl_learning_sources(packet_id TEXT NOT NULL REFERENCES pl_learning_packets(id) ON DELETE CASCADE, job_id TEXT NOT NULL, PRIMARY KEY(packet_id,job_id));
CREATE TABLE pl_learning_consents(packet_id TEXT PRIMARY KEY REFERENCES pl_learning_packets(id) ON DELETE CASCADE, owner_id TEXT NOT NULL, owner_version INTEGER NOT NULL);
CREATE TABLE pl_learning_drafts(id TEXT PRIMARY KEY, packet_id TEXT NOT NULL REFERENCES pl_learning_packets(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE pl_learning_decisions(draft_id TEXT PRIMARY KEY REFERENCES pl_learning_drafts(id) ON DELETE CASCADE, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TRIGGER pl_learning_job_erasure BEFORE DELETE ON pl_jobs BEGIN
 SELECT RAISE(ABORT,'CHECK constraint failed: held_learning_source') WHERE EXISTS(
  SELECT 1 FROM pl_learning_sources source JOIN pl_holds held ON held.subject_kind='job' AND held.subject_id=source.job_id
  WHERE source.packet_id IN (SELECT packet_id FROM pl_learning_sources WHERE job_id=OLD.id)
   AND held.released_at IS NULL AND (held.kind='legal_hold' OR held.until>=date('now'))
 );
 DELETE FROM pl_learning_packets WHERE id IN (SELECT packet_id FROM pl_learning_sources WHERE job_id=OLD.id);
END;

-- Erasure removes replay payloads as well as the product's source packet.
CREATE TRIGGER pl_learning_packet_erasure BEFORE DELETE ON pl_learning_packets BEGIN
 DELETE FROM agent_door_calls WHERE json_extract(outcome,'$.result.record.packet_id')=OLD.id OR json_extract(outcome,'$.result.record.packet.id')=OLD.id;
 DELETE FROM agent_door_approvals WHERE json_extract(saved,'$.args.packet_id')=OLD.id;
 DELETE FROM agent_door_reviews WHERE json_extract(saved,'$.args.packet_id')=OLD.id;
END;
CREATE TRIGGER pl_learning_erasure_journal AFTER INSERT ON pl_erased_jobs BEGIN
 DELETE FROM pl_learning_packets WHERE id IN (SELECT packet_id FROM pl_learning_sources WHERE job_id=NEW.job_id);
END;

-- Erasure removes private forecast copies retained by transport replay and review receipts.
CREATE TRIGGER pl_agent_forecast_erasure BEFORE DELETE ON pl_jobs BEGIN
 DELETE FROM agent_door_calls
 WHERE json_extract(outcome,'$.result.record.packet.format')='plinth-agent-forecast-v1'
   AND json_extract(outcome,'$.result.record.packet.job_id')=OLD.id;
 DELETE FROM agent_door_approvals
 WHERE json_extract(saved,'$.tool') IN ('plinth.forecast.read','plinth.forecast.prepare')
   AND json_extract(saved,'$.args.job_id')=OLD.id;
 DELETE FROM agent_door_reviews
 WHERE json_extract(saved,'$.tool') IN ('plinth.forecast.read','plinth.forecast.prepare')
   AND json_extract(saved,'$.args.job_id')=OLD.id;
END;
